mapper.select:

SELECT voucher_id, state, epoch, recovery_id
FROM tb_activity_control
WHERE voucher_id=#{voucher}


SELECT COUNT(*)
FROM tb_seckill_voucher
WHERE voucher_id=#{voucher}

mapper.update:

UPDATE tb_activity_control
SET state='FROZEN', epoch=#{epoch}, recovery_id=#{id}, reason=#{reason}
WHERE voucher_id=#{voucher}

mapper.select:

SELECT COUNT(*)
FROM tb_purchase_order
WHERE request_id=#{request}
AND voucher_id=#{voucher}
AND user_id=#{user}

mapper.update:

UPDATE tb_seckill_request
SET phase=#{phase}, reservation=#{reservation}, reason=#{reason}, epoch=#{epoch}, updated_at_ms=#{now}
WHERE request_id=#{request}


UPDATE tb_outbox
SET state='DONE', claim_token=NULL, last_result='RECOVERY_TERMINAL'
WHERE request_id=#{request}

mapper.select:

SELECT COUNT(*)
FROM tb_purchase_order
WHERE voucher_id=#{voucher}


SELECT id, user_id, request_id, event_id
FROM tb_purchase_order
WHERE voucher_id=#{voucher}
AND id>#{after}
ORDER BY id
LIMIT #{limit}

mapper.update:

UPDATE tb_seckill_request
SET reservation='RELEASED', updated_at_ms=#{now}
WHERE voucher_id=#{voucher}
AND phase='CLOSED'
AND reservation='RESERVED'


UPDATE tb_compensation c
JOIN tb_seckill_request r ON c.request_id=r.request_id
SET c.state='RELEASED', c.updated_at_ms=#{now}
WHERE r.voucher_id=#{voucher}
AND r.phase='CLOSED'
AND r.reservation='RELEASED'


UPDATE tb_activity_control
SET state='NORMAL', reason=NULL
WHERE voucher_id=#{voucher}
AND epoch=#{epoch}


UPDATE tb_recovery_run
SET state=#{state}, updated_at_ms=#{now}
WHERE recovery_id=#{id}

mapper.select:

SELECT available_stock, accepted_request_count, created_order_count
FROM tb_recovery_run
WHERE recovery_id=#{id}

mapper.update:

UPDATE tb_activity_control
SET state=#{state}
WHERE voucher_id=#{voucher}
AND epoch=#{epoch}

mapper.select:

SELECT *
FROM tb_seckill_request
WHERE voucher_id=#{voucher}
AND request_id>#{after}
ORDER BY request_id
LIMIT #{limit}
